$string['settings:rag_min_similarity'] = 'Minimalne dopasowanie (cosinus)';
$string['settings:rag_min_similarity_desc'] = 'Odrzucaj pobrane fragmenty, których podobieństwo kosinusowe do pytania jest niższe niż ta wartość, dzięki czemu pytanie nie na temat lub ubogie w treść wstrzykuje mniej (lub zero) fragmentów, zamiast zawsze uzupełniać do Top-K słabymi dopasowaniami. Zakres od 0 do 1; 0 wyłącza bramkę. Właściwa wartość zależy od modelu osadzania: 0.25 pasuje do text-embedding-3-small. Zwiększ ją, aby być bardziej rygorystycznym (mniej kontekstu, bardziej na temat), zmniejsz ją, aby być bardziej liberalnym.';
$string['settings:rag_currentpage_boost'] = 'Premia za bieżącą stronę';
$string['settings:rag_currentpage_boost_desc'] = 'Niewielka premia dodawana do wyniku trafności fragmentów ze strony, którą uczący się aktualnie ogląda, tak aby pytania takie jak „wyjaśnij to” preferowały widoczną stronę, gdy wyniki są zbliżone. Wyłącznie kolejność: nie wymusza przepuszczenia nietrafnego fragmentu strony przez bramkę minimalnej trafności. Ustaw 0, aby wyłączyć.';
$string['settings:history_mode'] = 'Tryb wyboru historii';
$string['settings:history_mode_desc'] = 'Sposób wybierania wcześniejszych tur rozmowy przed wysłaniem ich do modelu. <strong>Semantyczny</strong> zachowuje tylko ostatnie tury istotne dla bieżącego pytania (i zawsze najnowszą wymianę), dzięki czemu nieaktualna, niezwiązana z tematem wcześniejsza tura nie zawyża kosztu ani nie sprowadza odpowiedzi na manowce; wykonuje jedno dodatkowe wywołanie osadzania na wiadomość. <strong>Chronologiczny</strong> zachowuje ostatnie pary „Max Conversation History” niezależnie od trafności (dotychczasowe zachowanie, bez dodatkowego wywołania). Jeśli osadzanie jest niedostępne, tryb semantyczny automatycznie przełącza się na chronologiczny.';
$string['settings:history_mode_semantic'] = 'Semantyczny (trafne ostatnie tury)';
$string['settings:history_mode_recency'] = 'Chronologiczny (ostatnie N par)';
$string['settings:history_semantic_minscore'] = 'Dolny próg trafności historii (cosinus)';
$string['settings:history_semantic_minscore_desc'] = 'W trybie semantycznej historii wcześniejsza tura jest zachowywana tylko wtedy, gdy jej podobieństwo do bieżącego pytania wynosi co najmniej tę wartość (najnowsza wymiana jest zawsze zachowywana). Zakres od 0 do 1; zależny od modelu. Zwiększ, aby być bardziej rygorystycznym (mniej historii), zmniejsz, aby zachować więcej.';
$string['settings:history_candidates'] = 'Okno kandydatów historii';
$string['settings:history_candidates_desc'] = 'W trybie semantycznej historii pod kątem trafności oceniane są tylko ostatnie pary w tej liczbie (ograniczenie kosztu). Pary starsze niż to okno nie są wysyłane. Utrzymuj tę wartość na poziomie „Max Conversation History” lub wyższym.';

// v5.11.0 - v6.2.0 strings (added 2026-06-10).
$string['settings:embed_provider_voyage'] = 'Voyage AI (voyage-3.5 — zalecany; +4 MTEB vs OpenAI 3-small, 4x kontekst, wielojęzyczny)';
$string['settings:rerank_heading'] = 'RAG: Wyszukiwanie dwuetapowe (re-ranking)';
$string['settings:rerank_heading_desc'] = 'Opcjonalny drugi etap wyszukiwania: podobieństwo cosinusowe wybiera top-N kandydujących fragmentów (domyślnie 50), następnie cross-encoder re-rankera ocenia każdą parę (zapytanie, fragment), a najlepsze top-K trafiają do podpowiedzi. Domyślnie wyłączone; w przypadku braku konfiguracji re-rankera lub jego awarii przełącza się na jednoetapowe wyszukiwanie cosinusowe.';
$string['settings:rerank_enabled'] = 'Wyszukiwanie dwuetapowe (Voyage rerank-2.5)';
$string['settings:rerank_enabled_desc'] = 'Gdy włączone, wyszukiwanie RAG staje się dwuetapowe: podobieństwo cosinusowe zwraca top-N kandydatów (domyślnie 50), następnie cross-encoder Voyage rerank-2.5 ocenia każdego i top-K trafia do podpowiedzi. Opublikowane wyniki: +15 Recall@10 enterprise, +39% NDCG BEIR. Rozliczanie ~$0,05/MTok. Wymaga <code>rerank_apikey</code> poniżej; gracefully wraca do jednoetapowego cosinusowego, gdy rerank zawiedzie lub nie jest skonfigurowany.';
$string['settings:rerank_apikey'] = 'Klucz API re-rankera';
$string['settings:rerank_apikey_desc'] = 'Klucz API Voyage AI do rerank-2.5. Zostaw puste, aby ponownie użyć klucza API osadzania powyżej (typowe wdrożenia Voyage współdzielą jeden klucz dla embed + rerank).';
$string['settings:rerank_model'] = 'Model re-rankera';
$string['settings:rerank_model_desc'] = 'Domyślnie <code>rerank-2.5</code>. Nowsze modele Voyage rerank można podać tutaj.';
$string['settings:rerank_apibaseurl'] = 'Bazowy URL API re-rankera';
$string['settings:rerank_apibaseurl_desc'] = 'Nadpisuje bazowy URL Voyage rerank. Zostaw puste, aby użyć bazowego URL API osadzania powyżej lub domyślnego Voyage (<code>https://api.voyageai.com/v1</code>).';
$string['settings:rerank_candidates'] = 'Okno kandydatów re-rankera';
$string['settings:rerank_candidates_desc'] = 'Ilu kandydatów cosinusowych top-N trafia do etapu ponownego rankingu. Domyślnie 20. Zmierzone na 1008 zapytaniach: 20 dorównuje 30 pod względem czułości (R@3 89,0 % wobec 89,3 %) przy koszcie mniejszym o jedną trzecią, a 50 kosztuje 2,5 raza więcej bez mierzalnego zysku. Poniżej 10 czułość spada. Koszt rośnie liniowo wraz z tą wartością.';
$string['settings:stt_selfhosted_heading'] = 'Własna transkrypcja (Whisper)';
$string['settings:stt_selfhosted_heading_desc'] = 'Uruchom speech-to-text na własnym sprzęcie bez kosztu za minutę. Wskaż [[tutorshort]] na dowolny serwer transkrypcji zgodny z OpenAI: Docker <code>whisper-server</code>, <code>speaches</code> (faster-whisper) lub serwer <code>whisper.cpp</code>. Gdy tu ustawiony jest URL serwera, staje się domyślną ścieżką STT; wybierz płatnego dostawcę w ustawieniu Aktywny dostawca STT powyżej, aby nadpisać. Jeśli serwer jest w sieci prywatnej lub plain http, dodaj jego host do listy zaufanych punktów końcowych SSRF w sekcji Bezpieczeństwo.';
$string['settings:stt_selfhosted_url'] = 'URL serwera własnego STT';
$string['settings:stt_selfhosted_url_desc'] = 'Bazowy URL serwera transkrypcji zgodnego z OpenAI, np. <code>http://10.0.0.5:8000</code>. [[tutorshort]] automatycznie dołącza <code>/v1/audio/transcriptions</code>; akceptowana jest również pełna ścieżka punktu końcowego. Zostaw puste, aby wyłączyć własny STT.';
$string['settings:stt_selfhosted_model'] = 'Model własnego STT';
$string['settings:stt_selfhosted_model_desc'] = 'Nazwa modelu przekazywana do serwera, zgodna z załadowanym modelem Whisper — np. <code>Systran/faster-whisper-small</code> dla speaches lub <code>large-v3</code>. Zostaw puste, aby wysłać <code>whisper-1</code>, który większość własnych serwerów akceptuje lub ignoruje.';
$string['settings:stt_selfhosted_apikey'] = 'Klucz API własnego STT';
$string['settings:stt_selfhosted_apikey_desc'] = 'Opcjonalny. Większość własnych serwerów jest bezkluczona w zaufanej sieci; ustaw to tylko gdy serwer wymaga tokenu bearer.';
