$string['settings:mastery_classifier_provider'] = 'Dostawca klasyfikatora';
$string['settings:mastery_classifier_provider_desc'] = 'Identyfikator dostawcy używany dla klasyfikatora opanowania per-tura. Zostaw puste, aby dziedziczyć domyślnego dostawcę AI. Domyślny <code>openai</code> w parze z modelem klasyfikatora <code>gpt-4o-mini</code> poniżej — najtańsza opcja TIER 1 dla klasyfikacji ze strukturalnym wyjściem (~$220/mies. oszczędności przy 100k MAU vs poziom czatu). Gdy ustawiony, wiersz w Dostawcach porównawczych z tym identyfikatorem dostawcy dostarcza klucz API, bazowy URL i temperaturę.';
$string['settings:premium_escalation_heading'] = 'Poziom eskalacji premium (A.10)';
$string['settings:premium_escalation_heading_desc'] = 'Opcjonalne per-tura routowanie do modelu premium (domyślnie Claude Opus 4.8) dla podpowiedzi, z którymi poziom czatu roboczy wyraźnie sobie nie radzi — zazwyczaj matematyka wieloetapowa, informatyka i rozumowanie naukowe. Rozstrzygnięty przez bake-off A.10 z 2026-06-09: Opus 4.8 wygrał z 14,97/15 vs 12,68/15 gpt-4o na trudnych podpowiedziach. Dwie ścieżki wyzwalania: dopasowania regex do wiadomości użytkownika LUB lista dozwolonych kursów eskalująca każdą turę. Domyślnie wyłączone. Przy ~5% eskalacji, oczekuj ~$700/miesiąc przy 100k [[unishort]] MAU ponad wydatki bazowe czatu.';
$string['settings:premium_escalation_enabled'] = 'Włącz routowanie eskalacji premium';
$string['settings:premium_escalation_enabled_desc'] = 'Gdy włączone, router per-tura sprawdza listę regex wyzwalaczy i listę dozwolonych kursów dla każdego wywołania czatu; pasujące tury są kierowane do dostawcy premium. Wraca do dostawcy roboczego, jeśli wiersz premium brakuje lub nie udaje się go zainicjować. Nadpisania administratora-LLM-pickera zawsze wygrywają niezależnie od tego.';
$string['settings:premium_escalation_provider'] = 'Dostawca premium';
$string['settings:premium_escalation_provider_desc'] = 'Identyfikator dostawcy do routowania wywołań premium. Musi pasować do wiersza w Dostawcach porównawczych (tak aby klucz API, bazowy URL i temperatura pochodziły z tego samego miejsca, które administratorzy już zarządzają). Domyślnie <code>claude</code>.';
$string['settings:premium_escalation_model'] = 'Model premium';
$string['settings:premium_escalation_model_desc'] = 'Nazwa modelu przekazywana do dostawcy premium. Domyślnie <code>claude-sonnet-5</code> zgodnie z werdyktem bake-off A.10.';
$string['settings:premium_escalation_triggers'] = 'Wyrażenia regex wyzwalaczy premium';
$string['settings:premium_escalation_triggers_desc'] = 'Jedno wyrażenie PCRE regex na linię (bez ograniczników; dopasowanie bez uwzględniania wielkości liter jest stosowane automatycznie). Linie zaczynające się od # są komentarzami. Zostaw puste, aby użyć wyselekcjonowanego domyślnego zestawu z bake-off A.10 (znaczniki STEM wieloetapowego: „derive", „prove that", „step by step", matematyka LaTeX, ogrodzenia kodu, big-O, całki, optymalizacja itp.).';
$string['settings:premium_escalation_course_tags'] = 'Lista dozwolonych kursów premium';
$string['settings:premium_escalation_course_tags_desc'] = 'Jeden prefiks skrótu nazwy kursu lub idnumber na linię. Każda tura w pasującym kursie jest automatycznie eskalowana niezależnie od regex wiadomości (używaj dla kursów intensywnych STEM, gdzie eskalacja powinna być domyślna). Dopasowanie jest prefiksem bez uwzględniania wielkości liter — „MATH" pasuje do MATH121, MATH205 itp.';
$string['settings:spend_cap_per_course_default'] = 'Domyślny limit wydatków per kurs (USD)';
$string['settings:spend_cap_per_course_default_desc'] = 'Defensywny limit stosowany do każdego kursu, który nie ma skonfigurowanego własnego limitu wydatków per kurs. Ustaw np. <code>30</code>, aby ograniczyć miesięczne wydatki dowolnego kursu do $30 bez konieczności dostrajania poszczególnych kursów. <code>0</code> = brak domyślnego (obowiązują tylko limity ogólnosystemowe i per-kurs-nadpisanie). Gdy kurs przekroczy 80% / 95% / 100% tego limitu, istniejący potok alertów spend-guard wysyła powiadomienie do administratora (lista odbiorców: <code>spend_notify_emails</code>, z fallbackiem do administratorów strony). Konkretny kurs zawsze może podnieść własny pułap, ustawiając wyższe nadpisanie per kurs.';
$string['settings:cost_anomaly_heading'] = 'Wykrywacz anomalii kosztów (v6.0)';
$string['settings:cost_anomaly_heading_desc'] = 'Codzienne zaplanowane zadanie (<code>cost_anomaly_check</code>) porównujące dzisiejsze ogólnosystemowe wydatki [[tutorshort]] z krocząca medianą z 7 dni. Wysyła e-mail do listy odbiorców <code>spend_notify_emails</code> (z fallbackiem do administratorów strony), gdy dzisiejsze wydatki przekraczają skonfigurowany mnożnik × mediana. Wykrywa trzy tryby awarii, które istniejące progi 80% / 95% / 100% limitu wydatków pomijają: (1) rozbiegany kurs, gdzie bezwzględny pułap nie jest przekroczony, ale jeden kurs nagle generuje 10x normalnego wolumenu, (2) przypadkowe włączenie poziomu premium, (3) błędne routowanie dostawcy. Domyślnie wyłączone; wewnętrzny odpowiednik [[tutorshort]] zapytania Redash pod adresem <code>.drafts/sola-redash-cost-anomaly-2026-06-09.md</code>.';
$string['settings:cost_anomaly_enabled'] = 'Włącz wykrywacz anomalii kosztów';
$string['settings:cost_anomaly_enabled_desc'] = 'Gdy włączone, codzienne zaplanowane zadanie ocenia dzisiejsze wydatki względem kroczącej mediany z 7 dni i wysyła e-mail do administratorów przy anomalii. Pierwsze 7 dni po włączeniu generują status <code>insufficient_history</code> (brak historycznej bazy danych) i nigdy nie wysyłają alertu. Idempotentne per dzień: flaga w <code>config_plugins</code> zatrzymuje powtarzające się e-maile, jeśli cron uruchomi się wielokrotnie.';
$string['settings:cost_anomaly_multiplier'] = 'Mnożnik anomalii';
$string['settings:cost_anomaly_multiplier_desc'] = 'Dzisiejsze wydatki muszą przekroczyć ten mnożnik × medianę z 7 dni, aby wyzwolić alert. Domyślnie <code>2.0</code>. Obniż do <code>1.5</code>, aby uzyskać wcześniejsze ostrzeżenia (więcej fałszywych pozytywów podczas nagłego wzrostu zapisów). Podnieś do <code>3.0</code>, jeśli użycie [[unishort]] jest wystarczająco burstowe, że skoki 2x są rutynowe.';
$string['task:cost_anomaly_check'] = 'Codzienna kontrola anomalii kosztów [[tutorshort]]';

// v6.4.0 signed policy bundle strings (added 2026-06-11).
$string['settings:policy_bundle_heading'] = 'Podpisany pakiet zasad (zdalne aktualizacje zachowania)';
$string['settings:policy_bundle_heading_desc'] = 'Zastosuj ustawienia zachowania (podpowiedzi, routing, wyzwalacze eskalacji, dostrajanie RAG, zasady wydatków) z kryptograficznie podpisanego pliku JSON bez wdrażania kodu. Codzienne zaplanowane zadanie pobiera URL pakietu, weryfikuje jego podpis Ed25519 względem poniższego klucza publicznego i stosuje ustawienia tylko wtedy, gdy każdy klucz jest na wbudowanej liście dozwolonych i wersja pakietu jest nowsza niż ostatnio zastosowana. Klucze API, URL-e, webhooki i ustawienia zabezpieczeń nigdy nie mogą być ustawiane przez pakiet. Twórz i podpisuj pakiety za pomocą <code>admin/cli/policy_bundle_tool.php</code> (keygen, sign, verify, status, sync).';
$string['settings:policy_bundle_enabled'] = 'Włącz synchronizację pakietu zasad';
$string['settings:policy_bundle_enabled_desc'] = 'Po włączeniu codzienne zadanie pobiera i stosuje podpisane pakiety. Domyślnie wyłączone. Wyłączenie natychmiast wstrzymuje wszystkie synchronizacje; już zastosowane ustawienia zachowują swoje wartości.';
$string['settings:policy_bundle_url'] = 'URL pakietu zasad';
$string['settings:policy_bundle_url_desc'] = 'HTTPS URL podpisanego JSON pakietu (na przykład obiekt S3 lub GitHub raw URL). URL przechodzi tę samą walidację SSRF co punkty końcowe dostawców AI; hosty sieci prywatnej lub plain-http wymagają wpisu na liście dozwolonych zaufanych punktów końcowych SSRF.';
$string['settings:policy_bundle_pubkey'] = 'Klucz publiczny pakietu zasad';
