$string['settings:active_learners_enabled'] = 'Pokaż wskaźnik aktywnych uczestników';
$string['settings:active_learners_enabled_desc'] = 'Pokazuje w panelu czatu, ile innych osób uczy się w tej chwili. To zachęta społeczna, a nie funkcja dydaktyczna, i odpytuje serwer raz na minutę dla każdego otwartego panelu, dlatego domyślnie jest wyłączona. Wskaźnik pojawia się tylko wtedy, gdy aktywne są co najmniej dwie inne osoby.';

$string['task:unanswered_check'] = '[[tutorshort]] kontrola pytań bez odpowiedzi';
$string['settings:unanswered_check_enabled'] = 'Ostrzegaj, gdy pytania pozostają bez odpowiedzi';
$string['settings:unanswered_check_enabled_desc'] = 'Wysyła e-mail do odbiorców powiadomień o wydatkach, gdy uczący się zadają [[tutorshort]] pytania i nie otrzymują odpowiedzi. Detektor anomalii kosztów uruchamia się tylko, gdy wydatki <em>rosną</em> — dostawca odrzucający każde wywołanie nic nie kosztuje i nie wywoła alertu. Tutaj monitorujemy stosunek pytań do odpowiedzi, który spada do zera, gdy dostawca przestaje działać. Jeśli lista powiadomień jest pusta, używani są administratorzy witryny.';
$string['settings:unanswered_window_hours'] = 'Okno kontroli (godziny)';
$string['settings:unanswered_window_hours_desc'] = 'Jak daleko wstecz sięga każde uruchomienie. Krótsze reaguje szybciej, ale wymaga wystarczającego ruchu.';
$string['settings:unanswered_min_questions'] = 'Minimalna liczba pytań przed alertem';
$string['settings:unanswered_min_questions_desc'] = 'Kurs jest oceniany dopiero po tylu pytaniach w oknie. Poniżej kilku uczących się zamykających kartę wygląda jak awaria.';
$string['settings:unanswered_min_answer_rate'] = 'Minimalny wskaźnik odpowiedzi';
$string['settings:unanswered_min_answer_rate_desc'] = 'Ostrzegaj, gdy odsetek pytań z odpowiedzią spadnie poniżej tej wartości. 0,5 wykrywa też awarię częściową. Ustaw 0, aby wyłączyć ten test.';

$string['analytics:course_hidden_suffix'] = '(ukryty)';

$string['settings:hidden_categories'] = 'Ukryte kategorie kursów';
$string['settings:hidden_categories_desc'] = 'Rozdzielona przecinkami lista nazw lub identyfikatorów kategorii kursów, w których asystent nie ma się pojawiać. Przykład: "Tworzenie kursów, 42". Asystent jest też automatycznie ukrywany po włączeniu trybu edycji.';
$string['settings:provider_heading'] = 'Dostawca AI i rozmowa';
$string['settings:provider_heading_desc'] = 'Skonfiguruj zaplecze AI, model oraz zachowanie w rozmowie.';
$string['settings:claude_temperature_allow_prefixes'] = 'Modele Claude akceptujące parametr temperature';
$string['settings:claude_temperature_allow_prefixes_desc'] = 'Jeden przedrostek nazwy modelu w wierszu. Modele Anthropic, których nazwa zaczyna się od jednego z nich, nadal akceptują parametr próbkowania <code>temperature</code>. W każdym modelu Claude niepasującym do przedrostka parametr temperature jest pomijany (modele klasy rozumowania od Opus 4.7 odrzucają go błędem HTTP 400). Pozostaw puste, aby użyć dostarczonej wartości domyślnej.';
$string['settings:max_tokens'] = 'Maksymalna długość odpowiedzi (tokeny)';
$string['settings:max_tokens_desc'] = 'Maksymalna liczba tokenów na jedną odpowiedź AI. Niższe wartości dają krótsze i szybsze odpowiedzi. 512 = około 2-3 zdania, 1024 = około 1-2 akapity, 2048 = dłuższe wyjaśnienia. Ustaw 0, aby nie stosować limitu (wartość domyślna dostawcy).';
$string['settings:profile_update_interval'] = 'Częstotliwość aktualizacji profilu studenta';
$string['settings:profile_update_interval_desc'] = 'Po tylu wiadomościach studenta w kursie asystent tworzy (lub odświeża) profil uczenia się, podsumowujący mocne i słabe strony, styl uczenia się oraz zainteresowania. Profil jest umieszczany w komunikacie systemowym, aby odpowiedzi były spersonalizowane. Ustaw 0, aby wyłączyć. Domyślnie: 10.';
$string['settings:enable_thinking'] = 'Rozszerzone rozumowanie (tylko Claude)';
$string['settings:enable_thinking_desc'] = 'Włącza adaptacyjne rozumowanie w modelach Claude. Claude sam decyduje, kiedy i jak długo analizuje problem przed udzieleniem odpowiedzi. Poprawia trafność przy złożonych pytaniach, ale zwiększa zużycie tokenów i opóźnienie. Treść rozumowania nie jest pokazywana studentom. Pozostali dostawcy ignorują to ustawienie.';
$string['settings:rag_sources_heading'] = 'Źródła treści dla RAG';
$string['settings:rag_sources_heading_desc'] = 'Wybierz, z jakich rodzajów treści kursu indekser RAG pobiera tekst. Wskaźniki stanu na <a href="{$a}">stronie administracji RAG</a> pokazują, czy każdy ekstraktor ma to, czego potrzebuje do działania (na przykład program pdftotext albo listę dozwolonych w Cloudflare).';
$string['settings:rag_extract_pdf'] = 'Indeksuj pliki PDF (mod_resource)';
$string['settings:rag_extract_pdf_desc'] = 'Pobiera tekst z przesłanych plików PDF za pomocą programu <code>pdftotext</code> (poppler). Ścieżka do programu jest wykrywana automatycznie; w razie potrzeby podaj ją poniżej.';
$string['settings:rag_pdftotext_path'] = 'Ścieżka do programu pdftotext';
$string['settings:rag_pdftotext_path_desc'] = 'Pozostaw puste, aby wykryć automatycznie (sprawdzane są <code>/usr/bin/pdftotext</code>, <code>/usr/local/bin/pdftotext</code> oraz <code>which pdftotext</code>). Wypełnij to pole tylko wtedy, gdy instalacja znajduje się w innym miejscu.';
$string['settings:rag_extract_docx'] = 'Indeksuj pliki DOCX (mod_resource)';
$string['settings:rag_extract_docx_desc'] = 'Pobiera tekst z przesłanych dokumentów Word za pomocą ZipArchive w PHP. Nie wymaga żadnych zewnętrznych zależności.';
$string['settings:rag_extract_pptx'] = 'Indeksuj pliki PPTX (mod_resource)';
$string['settings:rag_extract_pptx_desc'] = 'Pobiera tekst z przesłanych nowszych prezentacji PowerPoint za pomocą ZipArchive w PHP. Przechodzi przez XML slajdów i notatek prelegenta w kolejności slajdów; nie wymaga zewnętrznych zależności. Starsze binarne pliki <code>.ppt</code> nie są obsługiwane — zapisz takie prezentacje ponownie jako <code>.pptx</code>.';
$string['settings:rag_extract_h5p'] = 'Indeksuj treści H5P (mod_h5p)';
$string['settings:rag_extract_h5p_desc'] = 'Przechodzi przez JSON treści H5P i indeksuje wszystkie pola zawierające tekst (pytania, odpowiedzi, informacje zwrotne, opisy). Metadane typów treści H5P są szerokie; w przypadkach brzegowych należy się liczyć z pojedynczymi fałszywymi trafieniami.';
$string['settings:rag_extract_scorm'] = 'Indeksuj pakiety SCORM (mod_scorm)';
$string['settings:rag_extract_scorm_desc'] = 'Rozpakowuje pakiety SCORM i indeksuje plik <code>imsmanifest.xml</code>, wszystkie pliki <code>.html</code> oraz ciągi treści Articulate Storyline. <strong>Domyślnie wyłączone</strong>, ponieważ przetwarzanie SCORM bywa kosztowne. Maksymalny rozmiar pakietu określa <code>rag_scorm_max_mb</code>.';
$string['settings:rag_scorm_max_mb'] = 'Maksymalny rozmiar indeksowanego pakietu SCORM (MB)';
$string['settings:rag_scorm_max_mb_desc'] = 'Pomija pakiety SCORM większe niż ta wartość, aby uniknąć nadmiernego zużycia pamięci.';
$string['settings:rag_fetch_transcripts'] = 'Pobieraj transkrypcje osadzonych filmów i treści interaktywnych';
$string['settings:rag_fetch_transcripts_desc'] = 'Przeszukuje treści mod_page i mod_book w poszukiwaniu osadzonych ramek iframe (Synthesia, YouTube, Articulate, Genially) i pobiera adres URL transkrypcji powiązanej z każdym osadzeniem (szuka zarówno powyżej, jak i poniżej ramki). Wymaga wychodzącego połączenia HTTPS z tego serwera do hosta transkrypcji. <strong>Domyślnie wyłączone</strong>; włącz je, gdy host transkrypcji doda ten serwer do swojej listy dozwolonych (na przykład regułą dostępu po IP w Cloudflare).';
$string['settings:rag_iframe_host_patterns'] = 'Wzorce hostów ramek iframe';
$string['settings:rag_iframe_host_patterns_desc'] = 'Jedno wyrażenie regularne w wierszu, dopasowywane do atrybutu <code>src</code> ramki iframe. Każda pasująca ramka jest traktowana jako osadzenie interaktywne, którego transkrypcję należy powiązać i zindeksować. Wiersze zaczynające się od <code>#</code> są komentarzami.';
$string['settings:rag_transcript_url_pattern'] = 'Wzorzec adresu URL transkrypcji';
$string['settings:rag_transcript_url_pattern_desc'] = 'Wyrażenie regularne dopasowywane do adresów URL odnośników do transkrypcji. Indekser wybiera dla każdej wykrytej ramki iframe najbliższy pasujący odnośnik (powyżej lub poniżej) i łączy je ze sobą. Pozostaw puste, aby wyłączyć wiązanie transkrypcji.';
$string['settings:performance_heading'] = 'Wydajność';
$string['settings:performance_heading_desc'] = 'Określa, ile treści kursu trafia do komunikatu dla AI. Niższe wartości oznaczają szybsze odpowiedzi, ale mniej kontekstu dla AI.';
$string['settings:max_content_per_resource'] = 'Maksymalna treść na zasób (znaki)';
$string['settings:max_content_per_resource_desc'] = 'Maksymalna liczba znaków treści pobieranych z każdej strony lub rozdziału książki. Niższe wartości zmniejszają rozmiar komunikatu i przyspieszają odpowiedzi.';
$string['settings:max_total_content'] = 'Maksymalna łączna treść (znaki)';
$string['settings:max_total_content_desc'] = 'Maksymalna łączna liczba znaków treści kursu umieszczanych w komunikacie systemowym. Niższe wartości zmniejszają rozmiar komunikatu i przyspieszają odpowiedzi.';
$string['settings:spend_guard_heading'] = 'Ochrona wydatków i optymalizator';
$string['settings:spend_guard_heading_desc'] = 'Ustaw limity wydatków na LLM w danym okresie. Po osiągnięciu limitu [[tutorshort]] wstrzymuje żądania albo przechodzi na tańszego dostawcę z Twojego łańcucha awaryjnego. Bieżący stan wydatków i zalecenia optymalizatora znajdziesz na <a href="{$a}">stronie kosztów tokenów</a>.';
$string['settings:spend_cap_period'] = 'Okres limitu wydatków';
$string['settings:spend_cap_period_desc'] = 'Jak często limit wydatków jest zerowany. Zgodnie z kalendarzem: miesięczny zaczyna się 1. dnia miesiąca, tygodniowy w poniedziałek, a dzienny o północy.';
$string['settings:spend_cap_site'] = 'Limit wydatków dla całej witryny (USD)';
$string['settings:spend_cap_site_desc'] = 'Łączny limit w USD dla wszystkich kursów i funkcji w bieżącym okresie. <code>0</code> = bez ograniczeń. Poniższe limity poszczególnych funkcji mają pierwszeństwo, jeśli zostały ustawione.';
$string['settings:spend_cap_chat'] = 'Limit czatu (USD)';
$string['settings:spend_cap_chat_desc'] = 'Limit wyłącznie dla czatu i testów studentów. <code>0</code> = użyj limitu całej witryny.';
$string['settings:spend_cap_voice'] = 'Limit głosu (USD)';
$string['settings:spend_cap_voice_desc'] = 'Limit dla głosu (Realtime + TTS + STT). Głos to zwykle największa pozycja kosztowa — ogranicz go w pierwszej kolejności.';
$string['settings:spend_cap_rag'] = 'Limit RAG (USD)';
$string['settings:spend_cap_rag_desc'] = 'Limit dla wywołań osadzeń wykonywanych podczas indeksowania kursów.';
$string['settings:spend_cap_analytics'] = 'Limit analityki (USD)';
$string['settings:spend_cap_analytics_desc'] = 'Limit dla zapytań administracyjnych Learning Radar.';
$string['settings:spend_failover_chain'] = 'Łańcuch awaryjny';
$string['settings:spend_failover_chain_desc'] = 'Po osiągnięciu limitu [[tutorshort]] próbuje tych dostawców po kolei. Jeden wpis w wierszu, w formacie <code>capability:label</code>. Etykiety odnoszą się do wpisów w sekcji Dostawcy porównawczy (dla <code>chat</code> / <code>analytics</code>) albo Dostawcy głosu (dla <code>voice</code>). Wiersze zaczynające się od <code>#</code> są komentarzami. Przykład:<br><code>chat:claude-haiku<br>chat:ollama-local<br>voice:openai-prod<br>analytics:deepseek</code>';
$string['settings:failover_per_call_enabled'] = 'Przełączanie awaryjne dla każdego wywołania (v5.5.0)';
$string['settings:failover_per_call_enabled_desc'] = 'Po włączeniu każde wywołanie czatu opakowuje głównego dostawcę dekoratorem łańcucha awaryjnego. Przy przekroczeniu limitu czasu lub błędzie 5xx w wywołaniu [[tutorshort]] przechodzi do kolejnego wpisu w <strong>łańcuchu awaryjnym</strong> powyżej i otwiera 15-minutowy bezpiecznik dla dostawcy, który zawiódł. Przy każdym przejściu zapisywany jest wpis audytowy (<code>failover_fallthrough</code>); po włączeniu sprawdź Administracja -> [[tutorshort]] -> Dziennik audytu, aby upewnić się, że łańcuch działa poprawnie. Domyślnie wyłączone; włącz dopiero po zweryfikowaniu łańcucha i po potwierdzeniu przez Twoją instytucję, że dla każdego dostawcy w łańcuchu obowiązują wymagane umowy powierzenia przetwarzania danych.';
$string['settings:failover_timeout_chat'] = 'Przełączanie awaryjne: limit czasu czatu (sekundy)';
$string['settings:failover_timeout_chat_desc'] = 'Jak długo czekać na pierwszy token od dostawcy czatu przed przejściem dalej. Domyślnie 8 s. Niższe wartości szybciej przełączają przy wolnych dostawcach, kosztem fałszywych alarmów przy chwilowo wolnych żądaniach; wyższe dłużej utrzymują łańcuch przy dostawcy głównym. Uwzględniane tylko wtedy, gdy <strong>przełączanie awaryjne dla każdego wywołania</strong> jest włączone.';
$string['settings:spend_notify_emails'] = 'Odbiorcy alertów o wydatkach';
$string['settings:spend_notify_emails_desc'] = 'Rozdzielone przecinkami adresy e-mail, które mają być powiadamiane przy 80%, 95% i 100% limitu. Pozostaw puste, aby powiadamiać wszystkich administratorów witryny.';
$string['settings:opt_cost_weight'] = 'Optymalizator: waga kosztu';
$string['settings:opt_cost_weight_desc'] = 'Jak mocno optymalizator uwzględnia koszt przy szeregowaniu dostawców. 0.0 pomija koszt, 1.0 optymalizuje wyłącznie pod kątem kosztu. Rozpatrywane łącznie z wagą jakości.';
$string['settings:opt_quality_weight'] = 'Optymalizator: waga jakości';
$string['settings:opt_quality_weight_desc'] = 'Jak mocno optymalizator uwzględnia zadowolenie studentów (odsetek ocen pozytywnych) przy szeregowaniu dostawców. 0.0 pomija jakość.';
$string['settings:inactivity_reminder_enabled'] = 'Przypomnienia o braku aktywności';
$string['settings:inactivity_reminder_enabled_desc'] = 'Wysyła cotygodniową wiadomość e-mail do studentów, którzy nie weszli do swojego kursu przez ustaloną liczbę dni.';
$string['settings:inactivity_threshold_days'] = 'Próg braku aktywności (dni)';
$string['settings:inactivity_threshold_days_desc'] = 'Liczba dni bez aktywności przed wysłaniem wiadomości przypominającej.';
$string['settings:voice_providers_heading'] = 'Dostawcy głosu (Realtime, TTS, STT)';
$string['settings:voice_providers_heading_desc'] = 'Skonfiguruj jednego lub więcej dostawców API głosu. Te ustawienia są niezależne od dostawcy czatu powyżej oraz od dostawcy osadzeń RAG — głos ma własną listę dostawców, ponieważ obecnie tylko OpenAI i xAI udostępniają punkty końcowe Realtime przez WebSocket oraz TTS i STT. Za pomocą list poniżej wybierz, który zarejestrowany dostawca obsługuje każdą z funkcji. Jeśli nie zdefiniowano żadnych wierszy, używany jest starszy mechanizm pojedynczego klucza (klucz API Realtime powyżej albo główny klucz OpenAI). Witryna korzystająca z Together AI / Anthropic / DeepSeek / Gemini / Mistral do czatu musi skonfigurować tu co najmniej jeden wiersz, aby głos działał.';
$string['settings:voice_active_realtime'] = 'Aktywny dostawca Realtime';
$string['settings:voice_active_realtime_desc'] = 'Który skonfigurowany dostawca głosu obsługuje sesje agenta głosowego Realtime.';
$string['settings:voice_active_tts'] = 'Aktywny dostawca TTS';
$string['settings:voice_active_tts_desc'] = 'Który skonfigurowany dostawca głosu odczytuje odpowiedzi AI na głos.';
$string['settings:voice_active_stt'] = 'Aktywny dostawca STT';
$string['settings:voice_active_stt_desc'] = 'Który dostawca zamienia mowę studentów na tekst. Pozostaw puste, aby preferować własny serwer Whisper, jeśli jest skonfigurowany poniżej, a następnie pierwszy wiersz dostawców głosu albo starszy klucz.';
$string['settings:stt_selfhosted_enabled'] = 'Włącz własną transkrypcję';
$string['settings:stt_selfhosted_enabled_desc'] = 'Używa własnego serwera Whisper opisanego poniżej jako ścieżki zamiany mowy na tekst dla wejścia głosowego i Soapbox. Wymaga podania adresu URL serwera poniżej. Po wyłączeniu transkrypcja wraca do ścieżki hostowanej (OpenAI Whisper) albo przeglądarkowej, nawet jeśli adres URL jest ustawiony.';
$string['settings:stt_selfhosted_warm'] = 'Rozgrzej przy rozpoczęciu nagrania Soapbox';
$string['settings:stt_selfhosted_warm_desc'] = 'Po włączeniu rozpoczęcie nagrania Soapbox wysyła lekkie żądanie rozgrzewające (w miarę możliwości) do własnego serwera transkrypcji, dzięki czemu host skalujący się do zera (na przykład Cloud Run) zdąży wystartować, gdy student jeszcze nagrywa — opóźnienie zimnego startu pozostaje wtedy niewidoczne dla transkrypcji uruchamianej przy wysyłaniu. Nie działa, jeśli powyżej nie podano adresu URL własnego serwera. Domyślnie wyłączone.';
$string['settings:voice_tab_enabled'] = 'Włącz kartę Głos';
$string['settings:voice_tab_enabled_desc'] = 'Pokazuje kartę Głos na dolnym pasku nawigacji. Po wyłączeniu studenci widzą tylko karty Czat i Notatki. Funkcje głosowe (ćwiczenie rozmowy, ćwiczenie wymowy) pozostają dostępne przez podpowiedzi rozpoczynające rozmowę, jeśli włączono je osobno.';
$string['settings:soapbox_heading'] = 'Soapbox';
$string['settings:soapbox_heading_desc'] = 'Ćwiczenie wystąpień ustnych: sposób transkrypcji nagrań i kryteria, według których są oceniane. Włącz Soapbox dla poszczególnych kursów przełącznikiem Soapbox w sekcji Dydaktyka.';
$string['settings:soapbox_max_seconds'] = 'Maksymalna długość nagrania Soapbox (sekundy)';
$string['settings:soapbox_max_seconds_desc'] = 'Bezwzględny górny limit długości nagrania w każdym zadaniu. Prowadzący mogą ustawić krótszy zakres. Domyślnie 720 (12 minut).';
$string['settings:soapbox_max_recordings'] = 'Maksymalna liczba nagrań Soapbox na studenta i zadanie';
$string['settings:soapbox_max_recordings_desc'] = 'Bezwzględny górny limit liczby nagrań, jakie student może wykonać do jednego zadania, niezależnie od ustawienia liczby prób w zadaniu. Domyślnie 3.';
$string['settings:soapbox_retention_days'] = 'Okres przechowywania nagrań Soapbox (dni)';
$string['settings:soapbox_retention_days_desc'] = 'Jak długo nagranie jest przechowywane przed automatycznym usunięciem; transkrypcja, wynik i informacja zwrotna zostają zachowane. Ograniczone do 1–28 dni. Krócej znaczy lepsza minimalizacja danych. Domyślnie 7.';
$string['settings:soapbox_video_quality'] = 'Jakość wideo w Soapbox';
$string['settings:soapbox_video_quality_desc'] = 'Rozdzielczość i przepływność nagrania. To główny czynnik wpływający na koszt i przepustowość; osoba mówiąca w planie średnim jest dobrze czytelna w jakości standardowej. Niska nadaje się do słabych łączy; wysoka tylko wtedy, gdy liczą się szczegóły obrazu.';
$string['settings:soapbox_storage_bucket'] = 'Zasobnik magazynu Soapbox';
$string['settings:soapbox_storage_bucket_desc'] = 'Zasobnik S3 na nagrania. Domyślnie: współdzielony zasobnik archiwum.';
$string['settings:soapbox_storage_region'] = 'Region magazynu Soapbox';
$string['settings:soapbox_storage_region_desc'] = 'Region AWS zasobnika, na przykład us-east-1.';
$string['settings:soapbox_storage_prefix'] = 'Przedrostek kluczy magazynu Soapbox';
$string['settings:soapbox_storage_prefix_desc'] = 'Przedrostek kluczy wewnątrz zasobnika. Nagrania są przechowywane pod tą ścieżką, dzięki czemu reguła cyklu życia może je objąć.';
$string['settings:soapbox_storage_key'] = 'Identyfikator klucza dostępu magazynu Soapbox';
$string['settings:soapbox_storage_key_desc'] = 'Identyfikator klucza dostępu podmiotu IAM ograniczonego do operacji PutObject/GetObject/DeleteObject na powyższym przedrostku.';
$string['settings:soapbox_storage_secret'] = 'Tajny klucz dostępu magazynu Soapbox';
$string['settings:soapbox_storage_secret_desc'] = 'Tajny klucz dostępu odpowiadający powyższemu identyfikatorowi klucza dostępu.';
$string['settings:survey_heading'] = 'Ankieta dla studentów';
