$string['settings:usertesting_external_url'] = 'Adres URL formularza zewnętrznego (opcja C)';
$string['settings:usertesting_external_url_desc'] = 'Opcjonalnie: adres URL formularza zewnętrznego (na przykład Formularze Google lub Typeform). Użyj symboli zastępczych: {{userid}}, {{courseid}}, {{messages}}, {{session_minutes}}. Jeśli adres jest ustawiony, kliknięcie "Testy użyteczności" otwiera go z wypełnionym kontekstem. Pozostaw puste, aby korzystać wyłącznie z panelu testowego w widżecie.';
$string['settings:footer_links_heading'] = 'Odnośniki w stopce';
