$string['settings:feedback_link_label_desc'] = 'Zastępuje tekst odnośnika do opinii w stopce, na przykład "Prześlij opinię o [[tutorshort]] do zespołu IT". Pozostaw puste, aby użyć domyślnej przetłumaczonej etykiety "Opinie".';
$string['settings:feedback_panel_intro'] = 'Wprowadzenie w panelu opinii';
