$string['settings:anomaly_digest_enabled_desc'] = 'Uruchamia codzienne zadanie zestawienia anomalii. Domyślnie działa cicho — odzywa się tylko wtedy, gdy wskaźnik przekroczy próg.';
$string['settings:anomaly_digest_threshold_pct'] = 'Próg alertu (%)';
$string['settings:anomaly_digest_threshold_pct_desc'] = 'Procentowa zmiana między bieżącym a poprzednim okresem, która wywołuje alert. Domyślnie: 50.';
